import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { TextareaComponent } from '../textarea/textarea.component';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { FactService } from '../../services/fact/fact.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { factdata, factIssues } from '../../interfaces/fact.interface';
import { NgClass } from '@angular/common';

@Component({
  selector: 'note',
  standalone: true,
  imports: [IconComponent, NgClass],
  templateUrl: './note.component.html',
  styleUrl: './note.component.scss'
})
export class NoteComponent {
  isFocus: boolean = false;
  // isedit: boolean = false;
  isEmpty: boolean = false;




  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() linkIds: string[] = [];
  isLoading: boolean = true;
  factlist: factdata[] = [];
  constructor(private factService: FactService, private cdr: ChangeDetectorRef, private tost: TostbarService) {

  }




  async ngOnInit() {
    this.factlist = await this.factService.getFactDetails(this.linkIds);
    if (!this.factlist.length) {
      this.isLoading = false;
      this.tost.error('No data found');
    }

    this.isLoading = false;
    this.cdr.detectChanges();

    this.factlist.map(a => a["jUpdatedTexts"] = [...(a.jTexts || [''])]);
    // if (this.factlist.length > 0) {
    //   const res = await this.factService.getFactIssuesAndLinks(this.linkIds);
    //   if (res.length) {
    //     const issues: factIssues[] = res[0] || [];
    //     this.factlist.map(a => a.issueList = issues.filter(b => b.nFSid == a.nFSid));
    //   }
    //   this.cdr.detectChanges();
    // }
  }

  updateJText(event: Event, g: any, index: number): void {
    const target = event.target as HTMLElement;

    // this.jTexts[index] = target.innerHTML;
    if (!g.jUpdatedTexts)
      g.jUpdatedTexts = [];

    g.jUpdatedTexts[index] = target.innerHTML;
    this.isEmpty = false;
    if (!target.innerText || target.innerText.trim() == '') {
      this.isEmpty = true;
    }
    this.cdr.detectChanges();
  }


  async SaveNote(g) {
    debugger;
    this.linkIds;

    if (!g.jUpdatedTexts?.length)
      g.jUpdatedTexts = g.jTexts;

    await this.factService.updateFactNote({ nFSid: g.nFSid, jTexts: g.jUpdatedTexts || [''] })
    g.jTexts = g.jUpdatedTexts;
    g.isedit = false;
  }

}
